            } else {
                cout << total_area - 2 << "\n";
            }
        }
    } else if (height % 2 != 0 && width % 2 != 0) {
        if (height == 1 || width == 1) {
            int max_dim = max(height, width);
            if (max_dim % 6 == 0) {
                cout << max_dim << "\n";
            } else {
                int base = (max_dim / 6) * 6;
                int r = max_dim % 6;
